if (!projectId || isNaN(projectId)) {
  throw new Error('Valid project_id is required');
}

// Escape single quotes for SQL safety
function escapeSql(str) {
  if (!str) return null;
  return String(str).replace(/'/g, "''");
}

function formatDate(date) {
  if (!date) return null;
  const d = new Date(date);
  return d.toISOString().split('T')[0];
}

// Build update fields dynamically
const updates = [];
const data = { project_id: projectId };

if (body.project_name !== undefined) {
  data.project_name = escapeSql(body.project_name.trim());
  updates.push(`project_name = '${data.project_name}'`);
}

if (body.start_date !== undefined) {
  data.start_date = formatDate(body.start_date);
  updates.push(`start_date = ${data.start_date ? "'" + data.start_date + "'" : "NULL"}`);
}

if (body.end_date !== undefined) {
  data.end_date = formatDate(body.end_date);
  updates.push(`end_date = ${data.end_date ? "'" + data.end_date + "'" : "NULL"}`);
}

if (body.status !== undefined) {
  data.status = escapeSql(body.status);
  updates.push(`status = '${data.status}'`);
}

if (body.description !== undefined) {
  data.description = body.description ? escapeSql(body.description) : null;
  updates.push(`description = ${data.description ? "'" + data.description + "'" : "NULL"}`);
}

if (body.is_yt_project !== undefined) {
  data.is_yt_project = body.is_yt_project === true || body.is_yt_project === 'true';
  updates.push(`is_yt_project = ${data.is_yt_project}`);
}

if (body.git_repository !== undefined) {
  data.git_repository = body.git_repository ? escapeSql(body.git_repository.trim()) : null;
  updates.push(`git_repository = ${data.git_repository ? "'" + data.git_repository + "'" : "NULL"}`);
}

if (updates.length === 0) {
  throw new Error('No fields to update');
}

data.updateClause = updates.join(', ');
return [{ json: data }];

